        }}
        .metadata {{
            display: grid;
            grid-template-columns: 200px 1fr;
            gap: 10px;
            margin: 20px 0;
        }}
        .metadata .label {{
            font-weight: bold;
            color: #4ec9b0;
        }}
        .screenshots {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }}
        .screenshot {{
            background: #2d2d30;
            padding: 15px;
            border-radius: 8px;
        }}
        .screenshot img {{
            width: 100%;
            border: 1px solid #3e3e42;
            border-radius: 4px;
        }}
        .screenshot h3 {{
            margin: 0 0 10px 0;
            color: #ce9178;
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }}
        th {{
            background: #2d2d30;
            text-align: left;
            padding: 10px;
            border: 1px solid #3e3e42;
        }}
        td {{
            padding: 8px;
            border: 1px solid #3e3e42;
        }}
        .metric-value {{
            color: #b5cea8;
            font-family: monospace;
        }}
    </style>
</head>
<body>
    <div class="header">
        <h1>E2E Test Evidence Report</h1>
        <p>{self.test_name}</p>
    </div>

    <h2>Test Metadata</h2>
